'use client';
import Link from 'next/link';import {useState} from 'react';import {ArrowUpRight, Menu, X} from 'lucide-react';import {products,socials,companyDescription} from '@/data/site';
export function Header(){const [open,setOpen]=useState(false);const links=[['About','/about'],['Products','/products'],['Team','/team'],['Contact','/contact'],['Future','/future']];return <header className="nav"><div className="container nav-inner"><Link href="/" className="wordmark">QORVAYN</Link><nav className="nav-links" aria-label="Primary navigation">{links.map(([label,href])=><Link key={href} href={href}>{label}</Link>)}<Link className="nav-cta" href="/contact">Get in touch <ArrowUpRight size={14}/></Link></nav><button className="menu-btn" aria-label="Toggle navigation" onClick={()=>setOpen(!open)}>{open?<X size={18}/>:<Menu size={18}/>}</button>{open&&<nav className="mobile-menu" aria-label="Mobile navigation">{links.map(([label,href])=><Link key={href} href={href} onClick={()=>setOpen(false)}>{label}</Link>)}<Link href="/contact" onClick={()=>setOpen(false)}>Get in touch</Link></nav>}</div></header>}
export function Footer(){return <footer className="footer"><div className="container"><div className="footer-grid"><div><div className="wordmark">QORVAYN</div><p>{companyDescription}</p><p className="meta">Bangladesh · Remote-first</p></div><div><h4>Explore</h4>{[['About','/about'],['Products','/products'],['Team','/team'],['Contact','/contact'],['Future','/future']].map(([l,h])=><Link key={h} href={h}>{l}</Link>)}</div><div><h4>Products</h4>{products.map(p=><Link key={p.slug} href={'/products/'+p.slug}>{p.name}</Link>)}</div><div><h4>Connect</h4><a href="mailto:theqorvayn@gmail.com">theqorvayn@gmail.com</a><div style={{display:'flex',gap:12,marginTop:18}}>{socials.map(([label,url])=><a key={label} href={url} target="_blank" rel="noreferrer" aria-label={label}><span style={{fontSize:12}}>{label}</span></a>)}</div></div></div><div className="footer-bottom"><span>© 2026 QORVAYN. All rights reserved.</span><span><Link href="/privacy">Privacy</Link> · <Link href="/terms">Terms</Link></span></div></div></footer>}
export function Layout({children}:{children:React.ReactNode}){return <><a className="skip" href="#main">Skip to content</a><Header/><main id="main">{children}</main><Footer/></>}
export function ConceptVisual({variant='blue'}:{variant?:string}){return <div className={'orb '+variant} aria-label="Abstract conceptual visual"><div className="orb-core"/></div>}
export function EmailCapture({button='Get updates'}:{button?:string}){return <form className="form" action="/contact/thank-you"><input type="email" aria-label="Email address" placeholder="Your email address" required/><button className="btn btn-primary" type="submit">{button}<ArrowUpRight size={16}/></button><small className="meta">Product updates only. Legal wording to be finalized before launch.</small></form>}
export function Reveal({children}:{children:React.ReactNode}){return <div>{children}</div>}
